package com.acme.mail;

import java.text.Normalizer;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import javax.mail.*;
import javax.mail.internet.*;
import java.util.Properties;

public class TenantEmailService {

    private static final Map<String, TenantConfig> tenantRegistry = new ConcurrentHashMap<>();
    private static final Pattern VALID_EMAIL = Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");
    private static final Pattern DOMAIN_PATTERN = Pattern.compile("^[a-z0-9.-]+$");

    static {
        tenantRegistry.put("tenant-alpha", new TenantConfig("tenant-alpha", "alpha-corp.com", "smtp.alpha-corp.com"));
        tenantRegistry.put("tenant-beta", new TenantConfig("tenant-beta", "beta-inc.org", "smtp.beta-inc.org"));
        tenantRegistry.put("tenant-admin", new TenantConfig("tenant-admin", "admin.internal", "smtp.internal"));
    }

    public SendResult sendEmail(String tenantId, String fromAddress, String toAddress, String subject, String body) {
        TenantConfig config = tenantRegistry.get(tenantId);
        if (config == null) {
            return SendResult.error("Unknown tenant: " + tenantId);
        }

        // Normalize the from address to canonical form for consistent validation
        String normalizedFrom = normalizeEmailAddress(fromAddress);
        String normalizedTo = normalizeEmailAddress(toAddress);

        // Validate email format
        if (!isValidEmail(normalizedFrom) || !isValidEmail(normalizedTo)) {
            return SendResult.error("Invalid email address format");
        }

        // Enforce tenant isolation: sender must belong to tenant's domain
        if (!belongsToTenant(normalizedFrom, config)) {
            return SendResult.error("Sender domain does not match tenant configuration");
        }

        // Additional security: prevent sending to internal admin domain from non-admin tenants
        if (!tenantId.equals("tenant-admin") && isInternalDomain(normalizedTo)) {
            return SendResult.error("Cannot send to internal domains from this tenant");
        }

        return dispatchEmail(config, normalizedFrom, normalizedTo, subject, body);
    }

    private String normalizeEmailAddress(String email) {
        if (email == null) return "";
        // NFC normalization to handle equivalent Unicode representations
        String normalized = Normalizer.normalize(email, Normalizer.Form.NFC);
        // Convert to lowercase for case-insensitive comparison
        return normalized.toLowerCase();
    }

    private boolean isValidEmail(String email) {
        return VALID_EMAIL.matcher(email).matches();
    }

    private boolean belongsToTenant(String email, TenantConfig config) {
        String domain = extractDomain(email);
        return config.getAllowedDomain().equals(domain);
    }

    private boolean isInternalDomain(String email) {
        String domain = extractDomain(email);
        // Check after normalization - domain should be pure ASCII at this point
        return domain.endsWith(".internal") || domain.equals("admin.internal");
    }

    private String extractDomain(String email) {
        int atIndex = email.lastIndexOf('@');
        if (atIndex < 0) return "";
        return email.substring(atIndex + 1);
    }

    private SendResult dispatchEmail(TenantConfig config, String from, String to, String subject, String body) {
        try {
            Properties props = new Properties();
            props.put("mail.smtp.host", config.getSmtpHost());
            props.put("mail.smtp.port", "587");
            props.put("mail.smtp.auth", "true");
            props.put("mail.smtp.starttls.enable", "true");

            Session session = Session.getInstance(props);
            MimeMessage message = new MimeMessage(session);
            message.setFrom(new InternetAddress(from));
            message.setRecipient(Message.RecipientType.TO, new InternetAddress(to));
            message.setSubject(subject);
            message.setText(body);

            // In production, Transport.send(message) would be called here
            return SendResult.success("Email queued for delivery from " + from + " to " + to);
        } catch (MessagingException e) {
            return SendResult.error("Failed to send: " + e.getMessage());
        }
    }

    public static class TenantConfig {
        private final String tenantId;
        private final String allowedDomain;
        private final String smtpHost;

        public TenantConfig(String tenantId, String allowedDomain, String smtpHost) {
            this.tenantId = tenantId;
            this.allowedDomain = allowedDomain;
            this.smtpHost = smtpHost;
        }

        public String getTenantId() { return tenantId; }
        public String getAllowedDomain() { return allowedDomain; }
        public String getSmtpHost() { return smtpHost; }
    }

    public static class SendResult {
        private final boolean success;
        private final String message;

        private SendResult(boolean success, String message) {
            this.success = success;
            this.message = message;
        }

        public static SendResult success(String msg) { return new SendResult(true, msg); }
        public static SendResult error(String msg) { return new SendResult(false, msg); }
        public boolean isSuccess() { return success; }
        public String getMessage() { return message; }
    }
}
